def collect_keys(req, txs):
    """Every key mentioned anywhere (map entries, ops, scan bounds, pairs)."""
    keys = set()
    for k in (req.get("initial") or {}):
        keys.add(k)
    for k in (req.get("final") or {}):
        keys.add(k)
    for t in txs:
        for op in t["ops"]:
            if op[0] == "scan":
                keys.add(op[1])
                keys.add(op[2])
                for pair in op[3]:
